arguments.command:
bash -lc 'cat > /tmp/patch_regexp.txt <<"PATCH"\
Patch to fix use-after-free and invalid pointer issues in njs_regexp.c (Symbol.split handling):

- Replace the garbled nested calls that populate captured with a clean, safe sequence:

for (i = 1; i <= ncaptures; i++) {
    njs_value_t captured;
    ret = njs_value_property_i64(vm, &z, i, &captured);
    if (njs_slow_path(ret == NJS_ERROR)) {
        return NJS_ERROR;
    }

    if (njs_value_is_string(captured)) {
        (void) njs_string_prop(vm, &sv, &captured);
    } else {
        sv.start = NULL;
        sv.size = 0;
        sv.length = 0;
    }

    ret = njs_array_string_add(vm, array, sv.start, sv.size, sv.length);
    if (njs_slow_path(ret != NJS_OK)) {
        return ret;
    }
}
PATCH
'  && echo DONE; cat /tmp/patch_regexp.txt
